slug: async-assert-throws-helper-not-awaited
stack: dotnet
topic: testing
level: middle
type: find-bug
grading: auto
tags: [async, exceptions, test-design]
code:
  language: csharp
  harness: statements
  source: |
    // Test: ParseAgeAsync("-5") must throw ArgumentException.
    await ExpectThrows<ArgumentException>(() => ParseAgeAsync("-5"));

    static async Task ExpectThrows<TException>(Func<Task> action) where TException : Exception
    {
        try
        {
            action();
            Console.WriteLine("FAIL: no exception");
        }
        catch (TException)
        {
            Console.WriteLine("PASS");
        }
    }

    static async Task<int> ParseAgeAsync(string text)
    {
        int age = int.Parse(text);
        if (age < 0)
        {
            throw new ArgumentException("Age must not be negative.", nameof(text));
        }
        await Task.Yield();
        return age;
    }
